  var ai = HOTKEYS_RANK[an], bi = HOTKEYS_RANK[bn];
  if (ai == null) ai = HOTKEYS_ORDER.length;
  if (bi == null) bi = HOTKEYS_ORDER.length;
  if (ai !== bi) return ai - bi;
  return an < bn ? -1 : an > bn ? 1 : 0;
