        var key = universal ? ('U|' + command) : ('N|' + rgroup + '|' + command);
        template(key, command, universal, parseKey(b.key), outName, name);
        var ek = rgroup + '\x00' + key;
        if (emitted[ek]) return; emitted[ek] = 1;                  // one row per binding per group
