function loadRecommended(_prev) {
  if (!(RECOMMENDED && RECOMMENDED.text)) return Promise.reject(new Error('no bundled recommended layout'));
  return Promise.resolve(buildDoc(parse(RECOMMENDED.text), RECOMMENDED.name || null));
}

